insert into public.competencia (id, trilha, topico_id, titulo, descricao, criterio, ordem) values
  ('py-comp-listas', 'python', 'py-est-01', 'Organizar dados em listas', 'Cria, acessa e altera sequências de valores relacionados.', 'Usa uma lista para registrar itens, percorrê-los e atualizar um elemento.', 10),
  ('py-comp-tuplas', 'python', 'py-est-02', 'Usar tuplas para dados agrupados', 'Reconhece quando uma sequência imutável representa um conjunto fixo de valores.', 'Cria e desempacota uma tupla e explica por que seus elementos não são alterados diretamente.', 20),
  ('py-comp-dicionarios', 'python', 'py-est-03', 'Consultar dados por chave', 'Representa informações nomeadas usando pares de chave e valor.', 'Cadastra e consulta dados por chave e trata uma chave ausente com segurança.', 30),
  ('py-comp-conjuntos', 'python', 'py-est-04', 'Trabalhar com valores únicos', 'Usa conjuntos para remover duplicatas e comparar grupos.', 'Identifica elementos únicos e aplica união ou interseção a dois grupos.', 40),
  ('py-comp-slicing', 'python', 'py-est-05', 'Selecionar partes de sequências', 'Acessa posições e fatias de strings, listas e tuplas.', 'Seleciona corretamente elementos usando índices e limites de slicing.', 50),
  ('py-comp-iterar-colecoes', 'python', 'py-est-06', 'Percorrer e resumir coleções', 'Itera sobre coleções para filtrar ou calcular resultados.', 'Percorre os elementos uma vez e produz o resultado pedido sem alterar a coleção por engano.', 60),
  ('py-comp-funcoes', 'python', 'py-est-07', 'Criar funções com responsabilidade clara', 'Encapsula uma tarefa em uma função reutilizável.', 'Define e chama uma função pequena com nome que descreve sua responsabilidade.', 70),
  ('py-comp-parametros', 'python', 'py-est-08', 'Passar argumentos para funções', 'Usa parâmetros posicionais e nomeados para variar o comportamento de uma função.', 'Chama uma função com argumentos compatíveis com sua assinatura.', 80),
  ('py-comp-retorno-escopo', 'python', 'py-est-09', 'Retornar resultados sem confundir escopos', 'Distingue valores locais e globais e retorna resultados explicitamente.', 'Usa return para entregar um resultado e evita depender de variável global para cálculo.', 90),
  ('py-comp-decomposicao', 'python', 'py-est-10', 'Decompor um problema em funções', 'Divide uma tarefa maior em etapas pequenas com entradas e saídas definidas.', 'Combina funções coesas para resolver um problema sem duplicar lógica.', 100),
  ('py-comp-projeto-alunos', 'python', 'py-est-10', 'Construir um cadastro de alunos', 'Integra listas, dicionários, pesquisas e funções em uma aplicação de terminal.', 'Outra pessoa consegue cadastrar, listar, pesquisar por matrícula e calcular médias; o estudante explica e demonstra os casos testados.', 110)
insert into public.atividade (id, trilha, topico_id, tipo, titulo, enunciado, configuracao, dificuldade, ordem, publicada) values
  ('py-quiz-est-01', 'python', 'py-est-01', 'quiz', 'Uma lista pode mudar', 'Você tem uma lista de tarefas e concluiu a primeira. Qual operação substitui o primeiro item por uma nova mensagem?', '{"multipla":false,"alternativas":[{"id":"a","texto":"tarefas[0] = \"Concluída\""},{"id":"b","texto":"tarefas(0) = \"Concluída\""},{"id":"c","texto":"tarefas = 0"},{"id":"d","texto":"tarefas.add(0, \"Concluída\")"}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-est-01', 'python', 'py-est-01', 'completar', 'Acesse o primeiro elemento', 'A lista começa na posição zero. Complete para exibir o primeiro nome.', '{"codigo":"nomes = [\"Bia\", \"Caio\", \"Dani\"]\nprint(nomes[___])","lacunas":[{"id":"indice","rotulo":"Índice do primeiro elemento"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-est-02', 'python', 'py-est-02', 'quiz', 'Quando uma tupla faz sentido?', 'Você quer guardar latitude e longitude como um par fixo. Qual afirmação sobre tuplas é correta?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Uma tupla representa uma sequência ordenada que não pode ser alterada diretamente."},{"id":"b","texto":"Uma tupla só pode guardar números inteiros."},{"id":"c","texto":"Tuplas sempre removem elementos repetidos."},{"id":"d","texto":"Uma tupla é escrita obrigatoriamente entre chaves."}]}'::jsonb, 'iniciante', 10, true),
  ('py-saida-est-02', 'python', 'py-est-02', 'saida', 'Desempacote uma tupla', 'Acompanhe a atribuição e informe a saída.', '{"codigo":"ponto = (3, 8)\nx, y = ponto\nprint(x + y)","rotuloResposta":"Número exibido"}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-est-03', 'python', 'py-est-03', 'quiz', 'Encontre pelo nome do campo', 'O dicionário aluno possui a chave "nome". Como obter esse valor?', '{"multipla":false,"alternativas":[{"id":"a","texto":"aluno[\"nome\"]"},{"id":"b","texto":"aluno.nome()"},{"id":"c","texto":"aluno(\"nome\")"},{"id":"d","texto":"aluno[0] sempre"}]}'::jsonb, 'iniciante', 10, true),
  ('py-erro-est-03', 'python', 'py-est-03', 'erro', 'Evite uma chave ausente', 'O código falha quando a chave "email" não existe. Qual opção permite fornecer um valor padrão?', '{"multipla":false,"alternativas":[{"id":"a","texto":"aluno.get(\"email\", \"não informado\")"},{"id":"b","texto":"aluno.email"},{"id":"c","texto":"aluno[0]"},{"id":"d","texto":"aluno.add(\"email\")"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-est-04', 'python', 'py-est-04', 'quiz', 'Valores sem repetição', 'Uma lista tem nomes repetidos e você quer obter os valores únicos. Qual estrutura faz isso diretamente?', '{"multipla":false,"alternativas":[{"id":"a","texto":"set(nomes)"},{"id":"b","texto":"tuple(nomes)"},{"id":"c","texto":"str(nomes)"},{"id":"d","texto":"range(nomes)"}]}'::jsonb, 'iniciante', 10, true),
  ('py-saida-est-04', 'python', 'py-est-04', 'saida', 'Conte valores únicos', 'Quantos elementos distintos aparecem?', '{"codigo":"cores = {\"azul\", \"verde\", \"azul\"}\nprint(len(cores))","rotuloResposta":"Quantidade exibida"}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-est-05', 'python', 'py-est-05', 'quiz', 'Leia uma fatia', 'Em texto = "Python", qual expressão produz "yth"?', '{"multipla":false,"alternativas":[{"id":"a","texto":"texto[1:4]"},{"id":"b","texto":"texto[1:3]"},{"id":"c","texto":"texto[0:3]"},{"id":"d","texto":"texto[-1:2]"}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-est-05', 'python', 'py-est-05', 'completar', 'Pegue os três primeiros itens', 'Complete a fatia para criar uma nova lista com os três primeiros valores.', '{"codigo":"numeros = [4, 7, 2, 9, 1]\nprimeiros = numeros[___]\nprint(primeiros)","lacunas":[{"id":"fatia","rotulo":"Fatia que termina antes do índice 3"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-est-06', 'python', 'py-est-06', 'quiz', 'Percorra cada valor', 'Qual laço percorre diretamente cada nome da lista sem precisar acessar um índice?', '{"multipla":false,"alternativas":[{"id":"a","texto":"for nome in nomes:"},{"id":"b","texto":"if nome in nomes:"},{"id":"c","texto":"while nomes:"},{"id":"d","texto":"def nome in nomes:"}]}'::jsonb, 'iniciante', 10, true),
  ('py-desafio-est-06', 'python', 'py-est-06', 'desafio', 'Conte as notas aprovadas', 'Leia uma linha de números inteiros separados por espaço. Conte quantas notas são maiores ou iguais a 7 e exiba a quantidade. A entrada terá ao menos um número.', '{"codigoInicial":"notas = list(map(int, input().split()))\naprovadas = 0\n\n# Percorra as notas e conte as que atendem ao critério.\n\nprint(aprovadas)","entradaExemplo":"5 7 9 6 7\n","saidaExemplo":"3\n","linguagem":"python","limiteCaracteres":12000}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-est-07', 'python', 'py-est-07', 'quiz', 'Defina uma função', 'Qual palavra inicia a definição de uma função em Python?', '{"multipla":false,"alternativas":[{"id":"a","texto":"def"},{"id":"b","texto":"func"},{"id":"c","texto":"function"},{"id":"d","texto":"make"}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-est-07', 'python', 'py-est-07', 'completar', 'Crie uma função pequena', 'Complete a palavra-chave para definir a função saudacao.', '{"codigo":"___ saudacao():\n    print(\"Olá!\")\n\nsaudacao()","lacunas":[{"id":"palavra","rotulo":"Palavra-chave de definição"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-est-08', 'python', 'py-est-08', 'quiz', 'Passe argumentos nomeados', 'A função apresentar(nome, cidade) recebe dois parâmetros. Qual chamada informa os valores pelo nome?', '{"multipla":false,"alternativas":[{"id":"a","texto":"apresentar(cidade=\"Recife\", nome=\"Lia\")"},{"id":"b","texto":"apresentar(nome: \"Lia\", cidade: \"Recife\")"},{"id":"c","texto":"apresentar[\"Lia\", \"Recife\"]"},{"id":"d","texto":"apresentar(nome = cidade)"}]}'::jsonb, 'iniciante', 10, true),
  ('py-saida-est-08', 'python', 'py-est-08', 'saida', 'Argumento padrão', 'Qual mensagem será exibida quando a função é chamada sem informar o segundo argumento?', '{"codigo":"def mostrar(nome, saudacao=\"Olá\"):\n    print(f\"{saudacao}, {nome}!\")\n\nmostrar(\"Ivo\")","rotuloResposta":"Mensagem exibida"}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-est-09', 'python', 'py-est-09', 'quiz', 'return não é print', 'Qual é a diferença principal entre return e print dentro de uma função?', '{"multipla":false,"alternativas":[{"id":"a","texto":"return entrega um valor para quem chamou; print apenas exibe uma mensagem."},{"id":"b","texto":"return sempre grava um arquivo; print retorna uma lista."},{"id":"c","texto":"Não há diferença: ambos encerram o programa."},{"id":"d","texto":"print só pode ser usado fora de funções."}]}'::jsonb, 'iniciante', 10, true),
  ('py-completar-est-09', 'python', 'py-est-09', 'completar', 'Devolva o resultado', 'Complete a função para que a chamada possa usar o valor calculado.', '{"codigo":"def dobrar(numero):\n    ___ numero * 2\n\nresultado = dobrar(6)\nprint(resultado)","lacunas":[{"id":"retorno","rotulo":"Comando que devolve o cálculo"}]}'::jsonb, 'iniciante', 20, true),
  ('py-quiz-est-10', 'python', 'py-est-10', 'quiz', 'Divida o problema em etapas', 'Um sistema precisa pesquisar um aluno e calcular sua média. Qual desenho facilita testar e reaproveitar o código?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Criar funções pequenas, como buscar_aluno e calcular_media, com entradas e resultados claros."},{"id":"b","texto":"Colocar todo o programa em uma única função muito longa."},{"id":"c","texto":"Copiar o mesmo cálculo em cada tela do programa."},{"id":"d","texto":"Usar variáveis globais para todas as etapas."}]}'::jsonb, 'iniciante', 10, true),
  ('py-desafio-est-10', 'python', 'py-est-10', 'desafio', 'Calcule uma média com função', 'Leia uma quantidade N e, em seguida, N notas (uma por linha). Escreva uma função calcular_media(notas) que retorne a média aritmética. Exiba o resultado com duas casas decimais.', '{"codigoInicial":"def calcular_media(notas):\n    # Devolva a média das notas.\n    pass\n\nquantidade = int(input())\nnotas = [float(input()) for _ in range(quantidade)]\nprint(f\"{calcular_media(notas):.2f}\")","entradaExemplo":"3\n7\n8\n9\n","saidaExemplo":"8.00\n","linguagem":"python","limiteCaracteres":12000}'::jsonb, 'iniciante', 20, true),
  ('py-projeto-alunos', 'python', 'py-est-10', 'projeto', 'Projeto — cadastro e acompanhamento de alunos', 'Crie uma aplicação de terminal para cadastrar alunos, listar cadastros, pesquisar por matrícula e calcular a média das notas. Organize cada responsabilidade em funções pequenas e use estruturas de dados adequadas.', '{"objetivo":"Integrar listas, dicionários, busca, iteração e funções em um programa que resolve uma necessidade concreta.","requisitos":[{"id":"cadastro","titulo":"Cadastrar aluno","descricao":"Guardar matrícula, nome e ao menos duas notas; impedir ou explicar matrícula duplicada."},{"id":"listagem","titulo":"Listar alunos","descricao":"Exibir os alunos cadastrados com matrícula, nome e média calculada."},{"id":"pesquisa","titulo":"Pesquisar matrícula","descricao":"Encontrar e exibir um aluno pela matrícula; informar quando não existir."},{"id":"media","titulo":"Calcular média","descricao":"Calcular a média das notas de cada aluno sem repetir a lógica em vários lugares."},{"id":"funcoes","titulo":"Separar responsabilidades","descricao":"Criar funções pequenas para cadastrar, listar, pesquisar e calcular média."},{"id":"validacao","titulo":"Validar dados","descricao":"Tratar lista vazia, nota inválida e matrícula repetida sem apresentar sucesso incorreto."}],"criterios":[{"id":"fluxos","titulo":"Fluxos demonstráveis","descricao":"Demonstra cadastro, listagem, pesquisa existente e pesquisa inexistente."},{"id":"calculo","titulo":"Médias verificáveis","descricao":"Confere médias com valores simples e explica o cálculo."},{"id":"organizacao","titulo":"Organização legível","descricao":"Nomes claros, funções coesas e estruturas de dados usadas com propósito."},{"id":"compreensao","titulo":"Compreensão e testes","descricao":"Resumo descreve os casos testados e uma decisão de organização do código."}],"entregaveis":["Link público do repositório ou arquivo .zip de até 20 MB","Resumo de pelo menos 20 caracteres explicando o que testou e aprendeu","Autoavaliação honesta dos requisitos concluídos"],"instrucoes":"Envie um link público de GitHub, GitLab ou Bitbucket, ou um arquivo .zip de até 20 MB. No resumo, conte o que testou e como organizou as funções; marque apenas requisitos que você verificou. A equipe revisará o projeto e devolverá feedback.","limiteResumo":2000,"plataformas":["github.com","gitlab.com","bitbucket.org"]}'::jsonb, 'iniciante', 30, true)
insert into public.atividade_gabarito (atividade_id, configuracao) values
  ('py-quiz-est-01', '{"corretas":["a"],"explicacao":"Listas são mutáveis e começam no índice zero. Atribuir a uma posição existente substitui seu valor; parênteses não fazem indexação em Python."}'::jsonb),
  ('py-completar-est-01', '{"lacunas":{"indice":["0"]},"explicacao":"O primeiro elemento está no índice 0. O índice 1 acessaria Caio."}'::jsonb),
  ('py-quiz-est-02', '{"corretas":["a"],"explicacao":"Tuplas preservam a ordem e não permitem substituir diretamente seus elementos. São úteis para grupos fixos, como coordenadas."}'::jsonb),
  ('py-saida-est-02', '{"aceitas":["11"],"explicacao":"O desempacotamento associa 3 a x e 8 a y. A soma exibida é 11."}'::jsonb),
  ('py-quiz-est-03', '{"corretas":["a"],"explicacao":"Acesso por colchetes e chave recupera o valor correspondente. Notação de ponto não é a forma geral de acessar chaves de dicionário."}'::jsonb),
  ('py-erro-est-03', '{"corretas":["a"],"explicacao":"get aceita um valor padrão para quando a chave não existe, evitando KeyError neste caso."}'::jsonb),
  ('py-quiz-est-04', '{"corretas":["a"],"explicacao":"set cria um conjunto, que mantém elementos únicos. A ordem de exibição não é garantida."}'::jsonb),
  ('py-saida-est-04', '{"aceitas":["2"],"explicacao":"O conjunto guarda azul e verde uma vez cada. Repetir azul não cria um terceiro elemento."}'::jsonb),
  ('py-quiz-est-05', '{"corretas":["a"],"explicacao":"O início da fatia é incluído e o fim é excluído. Os índices 1, 2 e 3 correspondem a y, t e h."}'::jsonb),
  ('py-completar-est-05', '{"lacunas":{"fatia":["0:3",":3"]},"explicacao":"O fim 3 não é incluído, então a fatia contém os índices 0, 1 e 2. O início pode ser omitido para começar do primeiro elemento."}'::jsonb),
  ('py-quiz-est-06', '{"corretas":["a"],"explicacao":"for item in colecao percorre cada elemento diretamente. Usar índices é possível, mas não necessário quando o índice não importa."}'::jsonb),
  ('py-desafio-est-06', '{"testes":[{"entrada":"5 7 9 6 7\n","saida":"3\n"},{"entrada":"1 2 3\n","saida":"0\n"},{"entrada":"7\n","saida":"1\n"},{"entrada":"10 8 6 4\n","saida":"2\n"}],"explicacao":"Percorra cada nota e incremente o contador somente quando ela for maior ou igual a 7. Inclua o limite 7 no teste, pois a regra diz maior ou igual."}'::jsonb),
  ('py-quiz-est-07', '{"corretas":["a"],"explicacao":"def inicia uma definição de função. O bloco da função precisa estar indentado e só executa quando a função é chamada."}'::jsonb),
  ('py-completar-est-07', '{"lacunas":{"palavra":["def"]},"explicacao":"def define a função; saudacao() chama a função já definida."}'::jsonb),
  ('py-quiz-est-08', '{"corretas":["a"],"explicacao":"Argumentos nomeados usam o sinal de igual e podem ser passados em ordem diferente da definição. A sintaxe não usa dois-pontos."}'::jsonb),
  ('py-saida-est-08', '{"aceitas":["Olá, Ivo!"],"explicacao":"saudacao tem o valor padrão Olá. Como a chamada fornece apenas nome, a função usa esse padrão."}'::jsonb),
  ('py-quiz-est-09', '{"corretas":["a"],"explicacao":"return entrega um resultado que pode ser guardado ou usado por outra expressão. print apenas escreve na saída e não substitui o retorno."}'::jsonb),
  ('py-completar-est-09', '{"lacunas":{"retorno":["return"]},"explicacao":"return encerra a chamada atual e entrega o valor calculado. Por isso resultado recebe 12."}'::jsonb),
  ('py-quiz-est-10', '{"corretas":["a"],"explicacao":"Funções pequenas com responsabilidades e contratos claros podem ser testadas separadamente e combinadas. Isso reduz duplicação e facilita localizar erros."}'::jsonb),
  ('py-desafio-est-10', '{"testes":[{"entrada":"3\n7\n8\n9\n","saida":"8.00\n"},{"entrada":"2\n0\n10\n","saida":"5.00\n"},{"entrada":"4\n6.5\n7.5\n8\n10\n","saida":"8.00\n"}],"explicacao":"A função deve devolver a soma das notas dividida pela quantidade. A formatação com .2f é aplicada na saída; a função pode retornar um número decimal."}'::jsonb)
