-- Prática de Estruturas de dados e funções. O desafio preexistente é preservado.

on conflict (id) do update set
  trilha = excluded.trilha, topico_id = excluded.topico_id, titulo = excluded.titulo,
  descricao = excluded.descricao, criterio = excluded.criterio, ordem = excluded.ordem;

on conflict (id) do update set
  trilha = excluded.trilha, topico_id = excluded.topico_id, tipo = excluded.tipo,
  titulo = excluded.titulo, enunciado = excluded.enunciado, configuracao = excluded.configuracao,
  dificuldade = excluded.dificuldade, ordem = excluded.ordem, publicada = excluded.publicada,
  atualizado_em = now();

on conflict (atividade_id) do update set configuracao = excluded.configuracao, atualizado_em = now();

on conflict do nothing;

-- O bucket de entregas continua privado e restrito a ZIPs do próprio aluno.
drop policy if exists "Alunos enviam seus arquivos de projeto" on storage.objects;
create policy "Alunos enviam seus arquivos de projeto"
on storage.objects for insert to authenticated
with check (
  bucket_id = 'entregas-projetos'
  and (storage.foldername(name))[1] = (select auth.uid()::text)
  and (storage.foldername(name))[2] in ('py-projeto-financeiro', 'py-projeto-apresentacao', 'py-projeto-calculadora', 'py-projeto-media', 'py-projeto-alunos')
  and storage.extension(name) = 'zip'
);
